from pathlib import Path

path = Path('app/src/main/java/com/clickgo/passageiro/MainActivity.java')
text = path.read_text(encoding='utf-8')

def repl(old, new, name):
    global text
    if old not in text:
        raise SystemExit(f'Trecho não encontrado: {name}')
    text = text.replace(old, new, 1)

# Controle de rotas assíncronas para impedir resposta antiga de mexer em uma tela nova.
repl('''    private int searchSeq = 0;\n    private int locationSeq = 0;\n''','''    private int searchSeq = 0;\n    private int locationSeq = 0;\n    private int routeSeq = 0;\n''','routeSeq')

# Login: campo de senha com botão de olho, e recuperação em tela própria.
old_login_password = '''        EditText pass = edit("Senha");\n        pass.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);\n        pass.setTransformationMethod(PasswordTransformationMethod.getInstance());\n        CheckBox show = new CheckBox(this);\n        show.setText("Mostrar senha");\n        show.setTextColor(Color.LTGRAY);\n        show.setOnCheckedChangeListener((b, c) -> {\n            int pos = pass.getSelectionStart();\n            pass.setTransformationMethod(c ? null : PasswordTransformationMethod.getInstance());\n            pass.setSelection(Math.max(0, Math.min(pos, pass.length())));\n        });\n        Button enter = primary("Entrar");\n        Button create = secondary("Criar conta");\n        TextView forgot = text("Esqueci minha senha", 15, YELLOW, true);\n'''
new_login_password = '''        EditText pass = edit("Senha");\n        pass.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);\n        pass.setTransformationMethod(PasswordTransformationMethod.getInstance());\n        Button eye = secondary("👁");\n        eye.setContentDescription("Mostrar ou ocultar senha");\n        final boolean[] passwordVisible = {false};\n        eye.setOnClickListener(v -> {\n            int pos = pass.getSelectionStart();\n            passwordVisible[0] = !passwordVisible[0];\n            pass.setTransformationMethod(passwordVisible[0] ? null : PasswordTransformationMethod.getInstance());\n            eye.setText(passwordVisible[0] ? "🙈" : "👁");\n            pass.setSelection(Math.max(0, Math.min(pos, pass.length())));\n        });\n        LinearLayout passwordRow = horizontal();\n        passwordRow.addView(pass, new LinearLayout.LayoutParams(0, dp(58), 1));\n        passwordRow.addView(spaceH(8));\n        passwordRow.addView(eye, new LinearLayout.LayoutParams(dp(58), dp(58)));\n        Button enter = primary("Entrar");\n        Button create = secondary("Criar conta");\n        TextView forgot = text("Esqueci minha senha?", 15, YELLOW, true);\n'''
