repl('''        card.addView(pass, lpMatch(dp(58)));\n        card.addView(show);\n        card.addView(space(8));\n''','''        card.addView(passwordRow, lpMatch(dp(58)));\n        card.addView(space(12));\n''','linha senha login')
repl('''        forgot.setOnClickListener(v -> recover(email.getText().toString().trim()));\n''','''        forgot.setOnClickListener(v -> showRecovery(email.getText().toString().trim()));\n''','clique esqueci senha')

# Recuperação de acesso: não chama a página de "Redefinir senha" dentro do app.
anchor = '''    private void showSignup() {\n'''
recovery = '''    private void showRecovery(String initialEmail) {\n        releaseMap();\n        cancelAddressSearch();\n        stopRidePolling();\n        LinearLayout body = vertical(BLACK);\n        body.setPadding(dp(24), dp(34), dp(24), dp(30));\n        Button back = secondary("← Voltar");\n        back.setOnClickListener(v -> showLogin());\n        body.addView(back, new LinearLayout.LayoutParams(dp(110), dp(50)));\n        body.addView(space(22));\n        body.addView(text("Recuperar acesso", 30, Color.WHITE, true));\n        body.addView(space(8));\n        body.addView(text("Informe o e-mail da sua conta. Vamos enviar um link para você criar uma nova senha.", 15, Color.LTGRAY, false));\n        body.addView(space(20));\n        EditText email = edit("E-mail");\n        email.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);\n        if (initialEmail != null && !initialEmail.isBlank()) email.setText(initialEmail);\n        body.addView(email, lpMatch(dp(58)));\n        body.addView(space(12));\n        Button send = primary("Enviar link de recuperação");\n        body.addView(send, lpMatch(dp(58)));\n        send.setOnClickListener(v -> recover(email.getText().toString().trim()));\n        setContentView(scroll(body, BLACK));\n    }\n\n    private void showSignup() {\n'''
repl(anchor, recovery, 'tela recuperação')

