release = '''    private void releaseMap() {\n        ++routeSeq;\n        MapView old = map;\n        map = null;\n        if (old != null) {\n            try { old.onPause(); } catch (Exception ignored) {}\n            try { old.onDetach(); } catch (Exception ignored) {}\n        }\n    }\n\n    private String cleanLabel(String label) {\n'''
repl(anchor2, release, 'releaseMap method')

